from hatchet_sdk import Hatchet, StickyStrategy

hatchet = Hatchet()
w = hatchet.workflow(name="test_wf", sticky=StickyStrategy.SOFT)

@w.task(name="step_a")
def step_a(input, ctx):
    return {"a": 1}

@w.task(name="step_b", parents=[step_a])
def step_b(input, ctx):
    return {"b": 2}

print("Workflow tasks:", w.tasks)
